        url = f"https://api.azure-api.com/collections/{collection}/query"
        headers = {"Authorization": "Bearer {{TOKEN}}"}
        data = {"question": query}

        response = requests.post(url, headers=headers, json=data, timeout=500)
        if response.status_code == 200:
            return response.json().get("context")[:5]  # Return top 5 chunks
        else:
